CREATE TABLE IF NOT EXISTS warehouse_sys.`sys_dim_enum_dict` (
  `biz_line` VARCHAR(32) COMMENT '业务线',
  `src_table_name` VARCHAR(128) COMMENT '来源表名',
  `src_field_name` VARCHAR(128) COMMENT '来源字段名',
  `src_field_value` VARCHAR(64) COMMENT '来源字段实际存储值',
  `src_value_label` VARCHAR(128) COMMENT '来源值语义/原始枚举名',
  `canonical_code` VARCHAR(64) COMMENT 'PRD标准状态码/标准编码',
  `canonical_value` VARCHAR(128) COMMENT 'PRD标准状态值',
  `status_desc` VARCHAR(1024) COMMENT '状态说明',
  `field_label` VARCHAR(64) COMMENT '标准枚举域',
  `source_basis` VARCHAR(32) COMMENT '取值来源: PRD / ODS / BOTH',
  `sort_order` INT COMMENT '排序字段'
) ENGINE=OLAP
DUPLICATE KEY(`biz_line`, `src_table_name`, `src_field_name`, `src_field_value`)
COMMENT '各业务线枚举类型映射维表'
DISTRIBUTED BY HASH(`biz_line`, `src_table_name`, `src_field_name`) BUCKETS 8
PROPERTIES (
  "replication_num" = "1"
);

